parameters.jsCode:
const raw = $json.text ?? $json.output ?? '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let plan;
try { plan = JSON.parse(cleaned); }
catch (e) { throw new Error('Planner returned invalid JSON: ' + raw.slice(0, 200)); }
if (!Array.isArray(plan.tasks)) throw new Error('No tasks array');
if (plan.tasks.length === 0) return { json: { needsClarification: true, question: plan.question } };
plan.tasks.forEach((t, i) => {
  if (!['researcher', 'coder'].includes(t.target)) throw new Error(`Task ${i}: bad target`);
  t.after = (t.after || []).filter(a => Number.isInteger(a) && a >= 0 && a < i);
});
return { json: { tasks: plan.tasks } };
